insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('adcf96ef-b418-569b-ab51-aa8ac54c0d98', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'If $9x + 4 = 67$, what is the value of $90x + 40$?', '["$7$", "$70$", "$130$", "$670$"]'::jsonb, 1, null),
  ('6a2f1874-caf8-549d-8c2e-e533c6ef3b4b', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'In the figure, line $p$ is parallel to line $r$, and line $t$ intersects both lines. What is the value of $x$?', '["$36$", "$72$", "$180$", "$252$"]'::jsonb, 2, '![figure](/q/nov25/001.webp)'),
  ('fba48764-a350-525b-9eed-ac23cdec26d6', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'A length of $450$ meters is equal to how many <u>decimeters</u>? ($1$ meter $=10$ decimeters)', '[]'::jsonb, 3, null),
  ('b5b5c287-7f2d-5789-8043-6eee5f111872', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The equation $58 = 2x + 2y$ gives the perimeter of a rectangular garden that has length $x$, in feet, and width $y$, in feet. The width of the garden is $14$ feet. What is the length, in feet, of the garden?', '[]'::jsonb, 4, null),
  ('c908aea7-5772-5f9c-8510-2ff11478cfc5', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The relationship between the variables $x$ and $y$ is defined by an exponential equation. When $x = 0$, the value of $y$ is $40$, and for every increase in the value of $x$ by $1$, the corresponding value of $y$ increases by $50%$ of its previous value. Which equation represents this relationship?', '["$y = 40(1.50)^{x}$", "$y = 40(1.05)^{x}$", "$y = 50(1.40)^{x}$", "$y = 50(1.04)^{x}$"]'::jsonb, 5, null),
  ('fcce531c-adb5-5733-a5f1-1a904858e85a', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The function $f$ is defined by $f(x) = \frac{1}{8x}$. What is the value of $f(x)$ when $x = 9$?', '[]'::jsonb, 6, null),
  ('d4ee36ca-e61b-5238-883d-21d3ee07c4b2', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The function $f$ is defined by $f(x) = 3x - \frac{1}{4}$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$- plane?', '["$(0,-\\frac{1}{4})$", "$(0,-3)$", "$(0,3)$", "$(0,4)$"]'::jsonb, 7, null),
  ('8c7663aa-8a37-5696-97ef-f618e483e483', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', '$x + 6y = 28$
$6y = 14$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '[]'::jsonb, 8, null),
  ('52afe9aa-f03b-59c2-b169-5e90bd317802', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The length of a side of square X is $9$ centimeters. The area of rectangle Y is $32$ square centimeters. What is the total area, in square centimeters, of square X and rectangle Y?', '["$145$", "$113$", "$82$", "$81$"]'::jsonb, 9, null),
  ('178d75ab-05b2-519f-961b-a7e9f32d64dd', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'During hibernation, American black bears do not eat or replenish calories. A certain black bear weighed $293$ pounds when entering hibernation and lost weight at a mean rate of $0.9$ pounds per day. At this rate, how many days after entering hibernation would the black bear weigh $230$ pounds?', '["$57$", "$63$", "$70$", "$207$"]'::jsonb, 10, null),
  ('25b45a12-8e50-542d-8d44-5235f5e71c09', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'The complete graph of $y = f(x)$ is shown. For how many values of $x$ does $f(x) = 0$?', '["One", "Two", "Three", "Four"]'::jsonb, 11, '![figure](/q/nov25/002.webp)'),
  ('aea26f66-0d1e-55ad-b009-76d9085f69a6', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', '$b^{2} - 4c = 7d$
The given equation relates the real numbers $b$, $c$, and $d$, where $d > \frac{4}{7}c$. Which equation correctly expresses $b$ in terms of $c$ and $d$?', '["$b = \\frac{7d+4c}{2}$", "$b = \\frac{7d-4c}{2}$", "$b = \\pm \\sqrt{7d + 4c}$", "$b = \\pm \\sqrt{7d - 4c}$"]'::jsonb, 12, null),
  ('38b27b05-cee8-57dd-ae1b-f4672b5de025', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', '$x^{2} - \frac{81}{16} = 0$
How many distinct real solutions does the given equation have?', '["Zero", "Exactly one", "Exactly two", "Infinitely many"]'::jsonb, 13, null),
  ('577f9b09-9d66-5108-9ef5-d71388dd8aa5', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'Triangles $ABC$ and $A^{′}B^{′}C^{′}$ are shown. Triangle $ABC$ is dilated by a scale factor of $6$ to form triangle $A^{′}B^{′}C^{′}$. If the length of $arAB$ is $18$, what is the length of $arA^{′}B^{′}$?', '["$3$", "$6$", "$24$", "$108$"]'::jsonb, 14, '![figure](/q/nov25/003.webp)'),
  ('391111a2-7b36-5dff-ad11-2380b4499264', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'What is the radius of the circle in the $xy$-plane defined by $(x + 3)^{2} + (y + 9)^{2} = 361$?', '[]'::jsonb, 15, null),
  ('7618e91e-b7ef-5dbc-8db1-4fb9b669797a', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'In the $xy$-plane, which of the following does NOT contain any points that are part of the solution set to $5x - 7y > 35$?', '["The $x$-axis", "The region where $x > 0$ and $y > 0$", "The region where $x < 0$ and $y < 0$", "The region where $x < 0$ and $y > 0$"]'::jsonb, 16, null),
  ('1d3a1a5d-6e8b-527c-8f3e-8da9ead269d6', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'If a person in this city is selected at random, which of the following is closest to the probability of selecting a person who is greater than 65 years old, given that the person is at least 18 years old?', '["$0.24$", "$0.32$", "$0.50$", "$0.92$"]'::jsonb, 17, '**The table shows the distribution of people in a certain city by age group.**

| Age group | Proportion |
| Less than 18 years old | $26%$ |
| 18-40 years old | $21%$ |
| 41-65 years old | $29%$ |
| Greater than 65 years old | $24%$ |'),
  ('b902ad30-135f-5af0-8beb-4e6edf157d39', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'Line $h$ is defined by $\frac{1}{2}x + \frac{1}{9}y - 54 = 0$. Line $j$ is perpendicular to line $h$ in the $xy$-plane. What is the slope of line $j$?', '["$-\\frac{9}{2}$", "$-\\frac{2}{9}$", "$\\frac{9}{2}$", "$\\frac{2}{9}$"]'::jsonb, 18, null),
  ('d05eec0e-bb96-57ce-8369-3a04d0e487d9', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', '$a,26,29,b,31,47,c$
For the given data set, the data values are listed in ascending order, where $a$, $b$, and $c$ are constants. For this data set, the mean is $36$, the median is $29$, and the range is $72$. What is the value of $c$?', '["$54$", "$72$", "$81$", "$98$"]'::jsonb, 19, null),
  ('34c2adde-83e1-538c-b44f-a0dbafec5d3e', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'In triangle $QRS$ shown, $QR < RS$. Which expression represents the length of $QS$?', '["$37\\cos Q$", "$37\\sin Q$", "$\\frac{37}{\\cos Q}$", "$\\frac{37}{\\sin Q}$"]'::jsonb, 20, '![figure](/q/nov25/004.webp)'),
  ('11311ba4-25df-5c15-a830-13811a333c84', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', '$y = 9(\frac{a}{7})^{x-c}- b$
How many times does the graph of the given equation in the $xy$-plane cross the $x$-axis, where $a$, $b$, and $c$ are positive constants such that $a > 7$ and $b > c$?', '["Zero", "One", "Two", "Three"]'::jsonb, 21, null),
  ('b9139c10-4686-5922-815b-df4441ace1db', 'df53c45a-1833-5367-98ad-9cdc85cf51c7', 'A certain town has an area of $4.29$ square miles. What is the area, in <u>square yards</u>, of this town? ($1$ mile $= 1,760$ yards)', '["$410$", "$7,550$", "$722,051$", "$13,288,704$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('adcf96ef-b418-569b-ab51-aa8ac54c0d98', 3, null, '**Choice D is correct.** From $9x + 4 = 67$ subtract 4 to get $9x = 63$, so $x = 7$. Then $90x + 40 = 90(7) + 40 =$ $630 + 40 = 670$, which matches choice D.
**Choice A is incorrect.** $7$ is the value of $x$, not of the expression $90x + 40$; substituting $x = 7$ gives a much larger value.
**Choice B is incorrect.** $70$ would be $10 \cdot 7$, but $90x + 40$ equals $10(9x + 4) = 10 \cdot 67 = 670$, not $70$.
**Choice C is incorrect.** $130$ is neither $90(7) + 40$ nor $10(9x + 4)$ for the given equation; direct substitution gives $670$, so $130$ is wrong.
**Faster approach:** Multiply the given equation by 10 to get $90x + 40 = 670$ immediately, avoiding solving for $x$ first.'),
  ('6a2f1874-caf8-549d-8c2e-e533c6ef3b4b', 1, null, '**Choice B is correct.** The angle labeled $x°$ and the angle labeled $72°$ are a pair of vertical angles formed by the intersection of line $t$ with line $p$, so they are congruent. Therefore $x = 72$.
**Choice A is incorrect.** $36$ is not equal to the given $72°$ and there is no halving relationship in the figure that would justify $36$.
**Choice C is incorrect.** $180$ would be a straight angle, but the two marked angles are not supplementary in the diagram; they are vertical and therefore equal, not summing to $180$.
**Choice D is incorrect.** $252$ is not related to the given $72°$ by any angle relationship in the figure and is therefore not correct.
**Faster approach:** Recognize immediately that the two marked angles are vertical angles at the same intersection, so they must be equal; pick $72$ without additional computation.'),
  ('fba48764-a350-525b-9eed-ac23cdec26d6', null, array['4500']::text[], '**The correct answer is 4500.** Each meter equals $10$ decimeters, so to convert $450$ meters to decimeters you multiply by $10$: $450 \times 10 = 4500$. Thus $450$ meters is $4500$ decimeters.
**Faster approach:** Multiply the number of meters by $10$ (move the decimal one place to the right) to convert to decimeters; e.g., $450 → 4500$. This works for any meter-to-decimeter conversion because $1 \text{m} = 10 \text{dm}$.'),
  ('b5b5c287-7f2d-5789-8043-6eee5f111872', null, array['15']::text[], '**The correct answer is 15.** The perimeter of the rectangle is given by $58 = 2x + 2y$. Substitute the width $y =$ $14$ into the equation to get $58 = 2x + 2(14) = 2x + 28$. Subtract 28 from both sides to obtain $30 = 2x$, and then divide both sides by 2 to find $x = 15$. Thus the length is 15 feet.
**Faster approach:** Combine like terms immediately by subtracting $2y$ (i.e., $2 \times 14 = 28$) from 58 to get $2x = 30$ , then divide by 2. For linear equations in one variable, substituting known values and isolating the variable is the quickest reliable method.'),
  ('c908aea7-5772-5f9c-8510-2ff11478cfc5', 0, null, '**Choice A is correct.** An exponential equation has form $y = a \cdot b^{x}$ where $a$ is the initial value $y(0)$ and $b$ is the growth factor per unit increase in $x$. Here $y(0) = 40$, so $a = 40$. Increasing by $50%$ each time means each step multiplies the previous value by $1 + 0.50 = 1.5$, so $b = 1.5$. Thus $y = 40(1.5)^{x}$, which is choice A.
**Choice B is incorrect.** Although it has the correct initial value 40, a base of $1.05$ corresponds to a $5%$ increase per step, not $50%$.
**Choice C is incorrect.** Its base $1.40$ means $40%$ growth per step and its initial value is $50$, not the given $40$.
**Choice D is incorrect.** It uses both the wrong initial value (50) and the wrong growth factor ($1.04$ corresponds to $4%$ growth).
**Faster approach:** Immediately set $y = 40 \cdot b^{x}$ and note "increases by 50%" means multiply by $1.5$, so pick $b =$ $1.5$ — giving $40(1.5)^{x}$. This direct identification works for any similar exponential-growth item.'),
  ('fcce531c-adb5-5733-a5f1-1a904858e85a', null, array['1/72']::text[], '**The correct answer is 1/72.** To evaluate $f(x) = \frac{1}{8x}$ at $x = 9$, substitute 9 for $x$ to get $f(9) = \frac{1}{8\cdot 9}$. Multiply $8 \cdot$ $9 = 72$, so $f(9) = \frac{1}{72}$.
**Faster approach:** Direct substitution and a quick mental multiplication (8×9=72) give the result immediately: the reciprocal of 72, $1/72$. This substitution method works for every problem that asks for a function value at a specified input.'),
  ('d4ee36ca-e61b-5238-883d-21d3ee07c4b2', 0, null, '**Choice A is correct.** The y-intercept is the point where $x = 0$. Evaluating $f(0)$ gives $f(0) = 3(0) - \frac{1}{4} = -\frac{1}{4}$, so the y-intercept is $(0,-\frac{1}{4})$.
**Choice B is incorrect.** That point would require $f(0) = -3$, but $f(0) = -\frac{1}{4}$, not $-3$.
**Choice C is incorrect.** That point would require $f(0) = 3$, which does not match $f(0) = -\frac{1}{4}$.
**Choice D is incorrect.** That point would require $f(0) = 4$, which is not equal to $-\frac{1}{4}$.
**Faster approach:** For any linear function in slope-intercept form $y = mx + b$, read off the y-intercept immediately as $(0,b)$; here $b = -\frac{1}{4}$.'),
  ('8c7663aa-8a37-5696-97ef-f618e483e483', null, array['14']::text[], '**The correct answer is 14.** From the second equation, $6y = 14$, so $y = 14/6 = 7/3$. Substitute into the first equation: $x + 6y = 28$ becomes $x + 6(7/3) = 28$. Simplify: $6(7/3) = 14$, so $x + 14 = 28$. Subtract 14 from both sides to get $x = 14$.
**Faster approach:** Recognize that $6y = 14$ gives $6y$ directly; substitute that into $x + 6y = 28$ to get $x + 14 =$ $28$, so $x = 14$. This substitution step is the quickest method for any similar two-equation system when one equation already gives a value for a whole expression like $6y$.'),
  ('52afe9aa-f03b-59c2-b169-5e90bd317802', 1, null, '**Choice B is correct.** The area of square X is $9^{2} = 81$ square centimeters. Adding rectangle Y’s area of $32$ square centimeters gives a total area of $81 + 32 = 113$ square centimeters, which matches choice B.
**Choice A is incorrect.** $145$ is much larger than the correct sum; it would correspond to $81 + 64$, but rectangle Y’s area is given as $32$, not $64$.
**Choice C is incorrect.** $82$ is only $1$ more than the square’s area and does not equal $81 + 32 = 113$.
**Choice D is incorrect.** $81$ is just the area of square X alone and omits the $32$ square centimeters from rectangle Y.
**Faster approach:** Compute the square’s area ($9^{2}$) and then immediately add the given rectangle area; for area-addition problems, direct computation and addition is the quickest reliable method.'),
  ('178d75ab-05b2-519f-961b-a7e9f32d64dd', 2, null, '**Choice C is correct.** The bear’s weight decreases linearly from 293 pounds at a rate of 0.9 pounds per day, so after $d$ days the weight is $293 - 0.9d$. Set this equal to 230: $293 - 0.9d = 230$, so $0.9d = 63$ and $d = 63/0.9 =$ $70$ days.
**Choice A is incorrect.** If $d = 57$, the weight would be $293 - 0.9(57) = 293 - 51.3 = 241.7$, not 230.
**Choice B is incorrect.** If $d = 63$, the weight would be $293 - 0.9(63) = 293 - 56.7 = 236.3$, not 230.
**Choice D is incorrect.** If $d = 207$, the weight would be $293 - 0.9(207) = 293 - 186.3 = 106.7$, far below 230.
**Faster approach:** Subtract to find total weight loss $293 - 230 = 63$ pounds, then divide by the daily loss $0.9$: $63/0.9 = 70$. This subtraction-then-division method works for all rate-change problems of this type.'),
  ('25b45a12-8e50-542d-8d44-5235f5e71c09', 2, null, '**Choice C is correct.** The x‑intercepts are the solutions of $f(x) = 0$. The graph crosses the x‑axis once on the far left (negative x), once as it rises from its minimum to a local maximum, and once more as it falls after that local maximum — for a total of three distinct x‑values where $y = 0$.
**Choice A is incorrect.** The graph crosses the x‑axis more than once, so there is not just one solution.
**Choice B is incorrect.** There are three crossings visible, not two.
**Choice D is incorrect.** There are only three x‑intercepts, so there are not four solutions.
**Faster approach:** Count how many times the curve crosses the x‑axis. Use the number of sign changes between consecutive extrema (and the ends) to quickly determine the number of zeros without computing values.'),
  ('aea26f66-0d1e-55ad-b009-76d9085f69a6', 2, null, '**Choice C is correct.** Starting from $b^{2} - 4c = 7d$, add $4c$ to both sides to get $b^{2} = 7d + 4c$. Taking square roots gives $b = \pm \sqrt{7d + 4c}$, which is exactly choice C.
**Choice A is incorrect.** It treats $b$ as linear and equals $\frac{7d + 4c}{2}$, but $b$ appears squared in the original equation, so $b$ should involve a square root, not division by 2.
**Choice B is incorrect.** Like A, it gives a linear expression $\frac{7d - 4c}{2}$; that does not satisfy $b^{2} = 7d + 4c$ in general.
**Choice D is incorrect.** It has the wrong sign inside the radical: $b^{2} = 7d + 4c$, not $7d - 4c$, so $\pm \sqrt{7d - 4c}$ is not equivalent to the given equation.
**Faster approach:** Isolate $b^{2}$ (add $4c$) and then take the square root; because $b$ is squared, the solution is $b =$ $\pm \sqrt{(\text{right}-\text{hand} \text{side})}$ every time.'),
  ('38b27b05-cee8-57dd-ae1b-f4672b5de025', 2, null, '**Choice C is correct.** Solve $x^{2} - \frac{81}{16} = 0$ by adding $\frac{81}{16}$ to both sides: $x^{2} = \frac{81}{16}$. Taking square roots gives $x = \pm \frac{9}{4}$, which are two distinct real solutions.
**Choice A is incorrect.** The equation does have real solutions (it factors or yields real square roots), so "Zero" is wrong.
**Choice B is incorrect.** There are two distinct values ($\frac{9}{4}$ and $-\frac{9}{4}$), so it is not exactly one solution. **Choice D is incorrect.** A quadratic equation of the form $x^{2} = c$ with nonzero $c$ has at most two solutions, so it cannot have infinitely many solutions.
**Faster approach:** Recognize $x^{2} = a$ with $a > 0$ always yields two real solutions, $\pm \sqrt{a}$; here $a = \frac{81}{16}$ so two solutions.'),
  ('577f9b09-9d66-5108-9ef5-d71388dd8aa5', 3, null, '**Choice D is correct.** A dilation about a point multiplies all lengths by the scale factor. Since triangle $A^{′}B^{′}C^{′}$ is the image of $ABC$ under a dilation with scale factor $6$, each side length is $6$ times the corresponding original length. So $A^{′}B^{′} = 6 \times AB = 6 \times 18 = 108.$
**Choice A is incorrect.** $3$ is $\frac{1}{6}$ of $18$, which would be the result of a dilation by $\frac{1}{6}$, not $6$.
**Choice B is incorrect.** $6$ is not related to the given segment length; it is the scale factor, not the image length.
**Choice C is incorrect.** $24$ is $18 + 6$ or $\frac{4}{3} \cdot 18$, neither of which corresponds to a dilation by $6$.
**Faster approach:** Multiply the given segment length by the dilation scale factor: $18 \times 6 = 108.$'),
  ('391111a2-7b36-5dff-ad11-2380b4499264', null, array['19']::text[], '**The correct answer is 19.** The given equation is in standard circle form $(x - h)^{2} + (y - k)^{2} = r^{2}$, where the radius is $r$. Here $(x + 3)^{2} + (y + 9)^{2} = 361$ matches that form with $r^{2} = 361$. Taking the positive square root (radius is nonnegative) gives $r =\sqrt{361} = 19$.
**Faster approach:** Recognize the standard form and take the square root of the constant on the right: $r =$ $\sqrt{361} = 19$. This works for any equation written as $(x - h)^{2} + (y - k)^{2} = r^{2}$.'),
  ('7618e91e-b7ef-5dbc-8db1-4fb9b669797a', 3, null, '**Choice D is correct.** Rearranging the inequality gives $y < \frac{5}{7}x - 5$, so the solution set is all points strictly below the line $y = \frac{5}{7}x - 5$. In region D, $x < 0$ and $y > 0$, so $5x \le 0$ and $-7y < 0$, making $5x - 7y \le 0$, which can never be greater than $35$. Thus no point with $x < 0,y > 0$ satisfies the inequality.
**Choice A is incorrect.** Points on the $x$-axis have $y = 0$; the inequality becomes $5x > 35$, i.e. $x > 7$, so points like $(8,0)$ are in the solution set.
**Choice B is incorrect.** In the first quadrant some points satisfy $y < \frac{5}{7}x - 5$ (for example $x = 20,y = 1$: $5(20) - 7(1) = 93 > 35$), so the region contains solutions.
**Choice C is incorrect.** With $x < 0,y < 0$ both terms can make $5x - 7y$ large positive (e.g. $x = -100,y =$ $-100$ gives $200 > 35$), so that region also contains solutions.
**Faster approach:** Solve for $y$ to get $y < \frac{5}{7}x - 5$ (points below the line). Then quickly note that any point with $x < 0,y > 0$ makes $5x - 7y \le 0$, so it cannot exceed $35$; eliminate D immediately.'),
  ('1d3a1a5d-6e8b-527c-8f3e-8da9ead269d6', 1, null, '**Choice B is correct.** The conditional probability is $P(> 65 ∣\ge 18) = \frac{P(> 65 \text{and} \ge 18)}{P(\ge 18)}$. Since everyone older than 65 is also at least 18, $P(> 65 \text{and} \ge 18) = 0.24$ and $P(\ge 18) = 1 - 0.26 = 0.74$. Thus the probability is $0.24/0.74 \approx 0.3243$, which is closest to $0.32$.
**Choice A is incorrect.** $0.24$ is the unconditional probability of being older than 65; the question asks for the probability given the person is at least 18, which requires dividing by $0.74$, producing a larger value.
**Choice C is incorrect.** $0.50$ is much larger than the computed conditional probability $0.3243$; there is no arithmetic that yields $0.50$ from $0.24$ and $0.74$ here.
**Choice D is incorrect.** $0.92$ is not consistent with these proportions and is far above any ratio obtainable from $0.24$ and $0.74$.
**Faster approach:** Remove the 26% under-18 group and renormalize the remaining percentages: the >65 share becomes $24/(100 - 26) = 24/74 \approx 0.324$, so pick the nearest choice (0.32).'),
  ('b902ad30-135f-5af0-8beb-4e6edf157d39', 3, null, '**Choice D is correct.** Put line h into slope-intercept form. From $\frac{1}{2}x + \frac{1}{9}y - 54 = 0$ we get $\frac{1}{9}y = -\frac{1}{2}x + 54$, so $y = -\frac{9}{2}x + 486$. Thus the slope of h is $-\frac{9}{2}$. A line perpendicular to h has slope equal to the negative reciprocal of $-\frac{9}{2}$, which is $\frac{2}{9}$.
**Choice A is incorrect.** $-\frac{9}{2}$ is the slope of line h itself, not the perpendicular line.
**Choice B is incorrect.** $-\frac{2}{9}$ is the negative reciprocal of $\frac{9}{2}$; it would be perpendicular to a line with slope $\frac{9}{2}$, not to h.
**Choice C is incorrect.** $\frac{9}{2}$ is the opposite sign reciprocal of h’s slope; the perpendicular slope must be the negative reciprocal of h’s slope, which here is positive $\frac{2}{9}$.
**Faster approach:** For $Ax + By + C = 0$, slope = $-A/B$; the perpendicular slope is the negative reciprocal, which simplifies to $B/A$. Apply these directly to avoid full rearrangement.'),
  ('d05eec0e-bb96-57ce-8369-3a04d0e487d9', 2, null, '**Choice C is correct.** With seven data values listed in ascending order, the median is the 4th value, so $b = 29$. The sum of all values is $7 \times 36 = 252$, so $a + 26 + 29 + 29 + 31 + 47 + c = 252$, which simplifies to $a + c = 90$ . The range is $c - a = 72$. Solving the system $a + c = 90$ and $c - a = 72$ gives $2c = 162$, so $c = 81$.
**Choice A is incorrect.** If $c = 54$, then from $a + c = 90$ we get $a = 36$, which would not keep the list in ascending order because $a$ would be greater than $26$.
**Choice B is incorrect.** If $c = 72$, then $a = 18$, but that yields $c - a = 54$, not the required range $72$.
**Choice D is incorrect.** If $c = 98$, then $a = -8$, which gives a range $106$, not $72$, and places $a$ out of order relative to the given list.
**Faster approach:** Use properties of a 7-term list: median = 4th term immediately gives $b$, then write sum $=$ $7\times$mean to get $a + c$, and use range $c - a$ to solve the two linear equations for $c$ quickly.'),
  ('34c2adde-83e1-538c-b44f-a0dbafec5d3e', 3, null, '**Choice D is correct.** In the right triangle QRS the right angle is at R, so $QS$ is the hypotenuse. Angle $Q$ has opposite side $RS$, which is labeled 37. By the definition of sine, $\sin Q = \frac{\text{opposite}}{\text{hypotenuse}} = \frac{37}{QS}$, so $QS = \frac{37}{\sin Q}$. **Choice A is incorrect.** $37\cos Q$ would give the side adjacent to angle $Q$, but the given 37 is the opposite side, not the adjacent side.
**Choice B is incorrect.** $37\sin Q$ would be a product of the known side and a trig ratio; it does not produce the hypotenuse when the known side is the opposite.
**Choice C is incorrect.** $\frac{37}{\cos Q}$ would be correct if 37 were the adjacent side, because $\cos Q = \frac{\text{adjacent}}{\text{hypotenuse}}$, but here 37 is opposite, so this expression is wrong.
**Faster approach:** Identify which side (opposite/adjacent) equals 37 for angle $Q$, then use $\sin = \text{opp}/\text{hyp}$ or $\cos = \text{adj}/\text{hyp}$ to solve for the hypotenuse directly.'),
  ('11311ba4-25df-5c15-a830-13811a333c84', 1, null, '**Choice B is correct.** Set $y = 0$ and solve $9(\frac{a}{7})^{x-c} - b = 0$, so $(\frac{a}{7})^{x-c} = \frac{b}{9}$. Because $a > 7$ the base $\frac{a}{7} > 1$, so the exponential function $(\frac{a}{7})^{x-c}$ is strictly increasing and takes every positive value. Since $b > 0$, $\frac{b}{9} > 0$, and there is exactly one real solution $x = c + \log _{a/7}(b/9)$; thus the graph crosses the $x$-axis exactly once.
**Choice A is incorrect.** The left side can equal $0$ for some $x$ because the exponential term can take the positive value $b/9$, so there is at least one intersection, not zero.
**Choice C is incorrect.** An exponential function with a fixed base $> 1$ is one-to-one, so it cannot equal the same positive value for two different $x$; therefore there cannot be two intersections.
**Choice D is incorrect.** For the same reason, there cannot be three intersections; exactly one solution exists.
**Faster approach:** Solve $0 = 9(\frac{a}{7})^{x-c} - b$ to get $(\frac{a}{7})^{x-c} = b/9$. Exponentials with base $> 1$ are one-to-one and produce every positive value, so there is exactly one solution (one crossing).'),
  ('b9139c10-4686-5922-815b-df4441ace1db', 3, null, '**Choice D is correct.** One square mile equals $1760^{2}$ square yards, and $1760^{2} = 3,097,600$. So $4.29$ square miles equals $4.29 \times 3,097,600 = 12,390,400 + 898,304 = 13,288,704$ square yards.
**Choice A is incorrect.** $410$ is far too small; it would correspond to multiplying by a factor near $95$ rather than $3,097,600$, so it does not reflect converting square miles to square yards.
**Choice B is incorrect.** $7,550$ is also far too small and inconsistent with the required factor of $1760^{2}$ for squaring the linear conversion.
**Choice C is incorrect.** $722,051$ is much smaller than the correct product $13,288,704$ and results from an incorrect arithmetic or conversion step.
**Faster approach:** Remember $1 \text{mi}^{2} = 1760^{2} = 3,097,600 \text{yd}^{2}$ and multiply by $4.29$ (or compute $3,097,600 \times$ $4 + \times 0.29$) to get the answer directly.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

