insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('0c91742b-914f-5141-a414-ef38a89124a2', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'Zuri has a goal to run at least $16$ miles per week while training for a race. This week, she has run $4$ miles. If $x$ represents the additional number of miles Zuri needs to run this week to meet her goal, which inequality represents this situation?', '["$4 - x \\le 16$", "$4 + x \\le 16$", "$4 - x \\ge 16$", "$4 + x \\ge 16$"]'::jsonb, 1, null),
  ('8f66dab6-e91e-53fe-970a-9b08b63a2c7b', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'In the figure shown, line $k$ intersects lines $r$ and $s$. If $w = 147$, which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?', '["$x = 33$", "$y = 147$", "$w + y = 180$", "$y + z = 180$"]'::jsonb, 2, '![figure](/q/nov25/005.webp)'),
  ('602011ad-ba74-510d-9d39-c89414e160e5', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'At a fundraiser, a family pays a fixed entrance fee. They then purchase food tickets, which each have the same cost. The table shows the relationship between the number of food tickets, $x$, that are purchased and the total amount paid $y$, in dollars, for both the entrance fee and the food tickets. Which equation represents the relationship between $x$ and $y$?', '["$y = \\frac{3}{2}x + 29$", "$y = \\frac{3}{2}x - 56$", "$y = \\frac{2}{3}x + \\frac{112}{3}$", "$y = \\frac{2}{3}x + \\frac{58}{3}$"]'::jsonb, 3, '![figure](/q/nov25/006.webp)'),
  ('4d161b0f-ae1a-5550-b204-539e3bdbbabc', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'A group of 10 gardeners recorded data on the germination rates of their tomato crop for one growing season. The scatterplot shows the relationship between the number of tomato seeds planted, $x$, and the number of tomato seeds that germinated, $y$, for each of the gardeners. A line of best fit is also shown. Which of the following is the best interpretation of the slope of the line of best fit in this context?', '["The number of tomato seeds planted is predicted to increase by $60$ seeds every $100$ days.", "The number of tomato seeds planted is predicted to increase by $300$ seeds every $100$ days.", "The number of tomato seeds that germinate is predicted to increase by $60$ seeds for every additional $100$ tomato seeds that are planted.", "The number of tomato seeds that germinate is predicted to increase by $300$ seeds for every additional $100$ tomato seeds that are planted."]'::jsonb, 4, '![figure](/q/nov25/007.webp)'),
  ('93607ab4-e24d-5c56-a498-5f313effab44', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The graph of $2x + y = 11$ in the $xy$-plane is a line. What is the slope of the line?', '[]'::jsonb, 5, null),
  ('f6d59189-f4e6-5d44-a65c-f31055208176', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$f(x) = 2x + 3$
$g(x) = 7x - 2$
$h(x) = 5x - 6$
The functions $f$, $g$, and $h$ are defined as shown. If $f(x) \cdot g(x) - h(x) = ax^{2} + bx + c$, where $a$, $b$, and $c$ are constants, what is the value of $b$?', '["$-5$", "$12$", "$20$", "$22$"]'::jsonb, 6, null),
  ('eca92027-b108-5712-996e-dfaf9e088b0d', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The function $f$ is defined by $f(x) = \frac{x-11}{5}$, and $f(a) = -18$, where $a$ is a constant. What is the value of $a$?', '["$-101$", "$-79$", "$-\\frac{79}{5}$", "$-\\frac{7}{5}$"]'::jsonb, 7, null),
  ('863a0eed-c7a1-530e-b271-9646a50d1155', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'Line $k$ also lies in the $xy$-plane and is defined by the equation $y = 4x$. At what point $(x,y)$ do lines $j$ and $k$ intersect?', '["$(5,20)$", "$(5,44)$", "$(6,24)$", "$(6,26)$"]'::jsonb, 8, 'The table shows values of $x$ and their corresponding values of $y$ for three points on line $j$ in the $xy$- plane.

| $x$ | $y$ |
| $0$ | $-10$ |
| $1$ | $-4$ |
| $2$ | $2$ |'),
  ('61734a74-66c1-5846-b94c-2dfb4ecb050e', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The function $h$ estimates an object’s height, in feet, above the ground $t$ seconds after the object is dropped, where $b$ is a constant. The function estimates that the object is $19.36$ feet above the ground when it is dropped at $t = 0$. How many seconds after being dropped does the function estimate the object will hit the ground?
$h(t) = -16t^{2} + b$', '[]'::jsonb, 9, null),
  ('9e939909-7f45-52bd-bddf-f9921e28b1bc', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$∣4x - 3∣ = -9$
How many solutions does the given equation have?', '["Zero", "One", "Two", "Infinitely many"]'::jsonb, 10, null),
  ('85292c61-7f54-52b1-88b4-b37aa47faa64', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The function $h$ is defined by $h(x) = a^{x} + b$, where $a$ and $b$ are positive constants. The graph of $y =$ $h(x)$ in the $xy$-plane passes through the points $(0,10)$ and $(2,13)$. What is the value of $ab$?', '["$13$", "$18$", "$20$", "$26$"]'::jsonb, 11, null),
  ('67bbbb84-7ba2-5043-a273-b4a218e5ab27', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'A circle has center $P$, and points $A$ and $B$ lie on the circle. The measure of arc $AB$ is $45°$ and the length of arc $AB$ is $4π$ units. What is the length, in units, of the radius of the circle?', '[]'::jsonb, 12, null),
  ('4b86274f-2079-5986-8234-f20fddc98746', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The function $f$ is defined by $f(x) = 56(0.19)^{x}$. For any positive integer $n$, the value of $f(n)$ is $p%$ less than the value of $f(n - 1)$. What is the value of $p$?', '["$19$", "$44$", "$56$", "$81$"]'::jsonb, 13, null),
  ('1888503d-4855-52b7-893f-94cd611bc3f8', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$x^{2} + (\sqrt{k - 3})x + 42 = 0$
In the given equation, $k$ is a constant. The equation has exactly one real solution. What is the value of $k$', '["171", "168", "165", "45"]'::jsonb, 14, null),
  ('6c554659-e6f4-53de-afd0-49d169e9aa78', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$x^{2} + y^{2} = 36$
$y = mx - \frac{b}{4}$
In the given system of equations, $m$ and $b$ are negative constants. In the $xy$-plane, the graphs of the equations in the given system intersect at the point $(-5,y)$, where $y < 0$. Which expression represents the value of $b$?', '["$\\frac{5m}{4} +\\frac{\\sqrt{11}}{4}$", "$\\frac{5m}{4} -\\frac{\\sqrt{11}}{4}$", "$-20m + 4\\sqrt{11}$", "$20m - 4\\sqrt{11}$"]'::jsonb, 15, null),
  ('0bd4cfb4-a731-5439-b59b-6290a98edd3a', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'A biologist mixed a solution that is $0.3%$ sodium chloride by mass with a solution that is $0.15%$ sodium chloride by mass to obtain a new solution, which has a mass of $80$ grams and contains $0.21$ grams of sodium chloride. How many grams of $0.3%$ sodium chloride solution did the biologist use?', '["$0.14$", "$20$", "$60$", "$79.86$"]'::jsonb, 16, null),
  ('3ffff47a-f761-5183-8baf-bba423fe41cf', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The data value $13$ is removed from data set A to create data set B, which consists of the remaining $10$ data values. Which statement best compares the median of data set A and the median of data set B?', '["The median of data set B is less than the median of data set A.", "The median of data set B is greater than the median of data set A.", "The median of data set B is equal to the median of data set A.", "There is not enough information to compare the medians of the two data sets."]'::jsonb, 17, 'For data set A, the table summarizes the distribution of the number of pieces of mail received by a business each day during a period of 11 days.

| Pieces of mail | Days |
| 0 | 2 |
| 3 | 2 |
| 4 | 2 |
| 5 | 2 |
| 6 | 1 |
| 7 | 1 |
| 13 | 1 |'),
  ('43ca8394-5f9d-58e0-a580-ebf8f80eaab3', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$\frac{x}{5} + \frac{y}{9} = \frac{47}{45}$
An engineer connects resistors in series, where the resistors in the series have a total resistance of $\frac{47}{45}$ ohms. In this series, there are $x$ resistors of type A, which each have a resistance of $a$ ohms, and $y$ resistors of type B, which each have a resistance of $b$ ohms. The given equation represents this situation. According to this equation, what is the positive difference between the value of $a$ and the value of $b$?', '["$47$", "$4$", "$\\frac{47}{15}$", "$\\frac{4}{45}$"]'::jsonb, 18, null),
  ('5bf31ba7-43bd-5ffd-a616-92a369cd3731', '145fa397-7bf7-51c4-ae71-bd6af659984f', '$9x^{2} + 8 = nx$
In the given equation, $n$ is a constant. The equation has exactly one solution. What is the value of $\frac{n^{2}}{8}$?', '[]'::jsonb, 19, null),
  ('43dc4f72-97dd-5682-84d3-cc934cbf1613', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'What is the value of $n$?', '["$2,100$", "$1,680$", "$840$", "$420$"]'::jsonb, 20, 'The table gives the areas and perimeters of two similar rectangles, where $n$ is a constant.

**Rectangles A and B**

| Rectangle | Area (square inches) | Perimeter (inches) |
| A | 630 | 210 |
| B | 2,520 | n |'),
  ('58b8d859-66ba-537e-bff5-edaa714861b0', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'The mass of object A is $444%$ of the mass of object B, and the mass of object A is $0.740%$ of the mass of object C. If the mass of object C is $p%$ of the mass of object B, what is the value of $p$?', '[]'::jsonb, 21, null),
  ('9eda255b-c31b-5a7d-a244-64bdb5dadecb', '145fa397-7bf7-51c4-ae71-bd6af659984f', 'Which expression is a factor of $y^{2}(x - 3) - 25(x - 3)^{3}$?', '["$y(x - 3)$", "$(x - 5)(x - 3)$", "$y - x - 3$", "$y + 5x - 15$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('0c91742b-914f-5141-a414-ef38a89124a2', 3, null, '**Choice D is correct.** Zuri wants to run at least $16$ miles total, and she has already run $4$ miles, so the total miles after running an additional $x$ miles is $4 + x$. “At least $16$” means this total is greater than or equal to $16$, so the inequality is $4 + x \ge 16$, which is choice D (and simplifies to $x \ge 12$).
**Choice A is incorrect.** $4 - x \le 16$ subtracts $x$ rather than adding the additional miles, so it does not represent adding miles to the existing $4$.
**Choice B is incorrect.** $4 + x \le 16$ uses addition correctly but the direction is wrong: it says the total is at most $16$, not at least $16$.
**Choice C is incorrect.** $4 - x \ge 16$ both subtracts $x$ (wrong operation) and would imply Zuri has already run at least $16$ before adding more, which contradicts the situation.
**Faster approach:** Translate “at least $16$” to $\ge 16$ and add the miles already run to the additional miles: $4 +$ $x \ge 16$.'),
  ('8f66dab6-e91e-53fe-970a-9b08b63a2c7b', 1, null, '**Choice B is correct.** In the figure $w$ is the angle at the intersection of $k$ with line $r$ in the upper-right position and $y$ is the angle in the same upper-right position at the intersection of $k$ with line $s$, so $w$ and $y$ are corresponding angles. If corresponding angles are equal, the two lines are parallel; since $w = 147$, the statement $y = 147$ makes the corresponding angles congruent and therefore proves $r ∥ s$.
**Choice A is incorrect.** $x = 33$ could be true because $x$ might be a supplementary partner to $w$ (since $147 +$ $33 = 180$), but knowing $x = 33$ gives no relation between angles at the intersection with line $s$, so it does not establish that $r$ and $s$ are parallel.
**Choice C is incorrect.** $w + y = 180$ would make $y = 33$ given $w = 147$, but those two angles are not shown as a same-side interior pair that would imply parallel lines; the picture shows $w$ and $y$ as corresponding angles, not interior consecutive angles, so this statement does not prove parallelism.
**Choice D is incorrect.** $y + z = 180$ only relates two angles at the intersection with line $s$ (a linear pair), which gives no information about line $r$; it does not connect angles on $r$ and $s$ and so cannot prove $r ∥ s$.
**Faster approach:** Identify corresponding, alternate interior, or same-side interior pairs; to prove parallelism set corresponding or alternate interior angles equal (or same-side interior supplementary) — here spot the corresponding-angle pair and check equality.'),
  ('602011ad-ba74-510d-9d39-c89414e160e5', 0, null, '**Choice A is correct.** We need to find the equation representing the relationship between the number of food tickets $x$ and the total amount paid $y$, which includes a fixed entrance fee and the cost per food ticket.
First, determine the cost per food ticket by finding the rate of change (slope) from the table values:
From 10 to 15 tickets, the total cost increases from \$44.00 to \$51.50.
The change in the number of tickets is $15 - 10 = 5$, and the change in cost is \$51.50 - \$44.00 = \$7.50.
The cost per ticket is therefore:
$\text{Cost} \text{per} \text{ticket} = \frac{7.50}{5} = 1.50$
The slope $m$ of the equation $y = mx + b$ is $\frac{3}{2}$, because $1.50 = \frac{3}{2}$.
Now, to find the entrance fee $b$ (the y-intercept), use one of the table points, say $(10,44)$:
$44 = \frac{3}{2}(10) + b$
$44 = 15 + b$
$b = 29$
So the equation is $y = \frac{3}{2}x + 29$.
Now, let’s briefly explain why the other options are incorrect:
**Choice B:** $y = \frac{3}{2}x - 56$ has the wrong y-intercept. We calculated it to be \$29, not \$56.
**Choice C:** $y = \frac{2}{3}x + \frac{112}{3}$ has an incorrect slope. The slope we calculated is $\frac{3}{2}$, not $\frac{2}{3}$.
**Choice D:** $y = \frac{2}{3}x + \frac{58}{3}$ also has an incorrect slope. The correct slope is $\frac{3}{2}$, not $\frac{2}{3}$.'),
  ('4d161b0f-ae1a-5550-b204-539e3bdbbabc', 2, null, '**Choice C is correct.** The line of best fit goes through approximately (0, 0) and (500, 300), so the slope is $\frac{300-0}{500-0} = 0.6$. That means for every 1 seed planted the model predicts 0.6 seeds germinate, which is equivalent to 60 seeds germinating for every additional 100 seeds planted.
**Choice A is incorrect.** It misinterprets the slope as a change in seeds planted per time (days), introducing an irrelevant unit and reversing the dependent/independent variables.
**Choice B is incorrect.** Like A, it uses days and gives the wrong magnitude; it also confuses which quantity changes with the other.
**Choice D is incorrect.** This claims 300 seeds germinate per 100 planted, which implies a slope of 3, far larger than the observed slope of 0.6.
**Faster approach:** Pick two clear points on the fitted line (here (0,0) and (500,300)), compute rise/run to get slope, then scale to per-100-seeds by multiplying by 100.'),
  ('93607ab4-e24d-5c56-a498-5f313effab44', null, array['-2']::text[], '**The correct answer is -2.** To find the slope of the line given by the equation $2x + y = 11$, solve for $y$ in terms of $x$ to put the equation into slope-intercept form $y = mx + b$. Subtract $2x$ from both sides to get $y = -2x +$ $11$. The coefficient of $x$ is the slope, so the slope is $-2$.
**Faster approach:** Rearranging to $y = mx + b$ is direct; equivalently, note that in a standard-form equation $Ax + By = C$, the slope is $-A/B$, so here it is $-2/1 = -2$ — a quick formula to use on any similar problem.'),
  ('f6d59189-f4e6-5d44-a65c-f31055208176', 1, null, '**Choice B is correct.** Compute $f(x) \cdot g(x) = (2x + 3)(7x - 2) = 14x^{2} + 17x - 6$. Subtract $h(x) = 5x - 6$ to get $14x^{2} + 17x - 6 - (5x - 6) = 14x^{2} + 12x + 0$. Thus $b = 12$.
**Choice A is incorrect.** $-5$ does not match the combined linear coefficient found after expanding and subtracting; the correct linear coefficient is $12$, not $-5$.
**Choice C is incorrect.** $20$ is too large; it would result from an arithmetic error in combining the $x$ terms.
**Choice D is incorrect.** $22$ is also incorrect; it does not equal the actual linear coefficient $12$ obtained by correct expansion and subtraction.
**Faster approach:** To get $b$ without full expansion, find the linear-term contributions: from $f \cdot g$ the $x$ term is $2x \cdot (-2) + 3 \cdot 7x = -4x + 21x = 17x$, then subtract the $5x$ from $h$ to get $17x - 5x = 12x$, so $b = 12$.'),
  ('eca92027-b108-5712-996e-dfaf9e088b0d', 1, null, '**Choice B is correct.** Start with $f(a) = \frac{a-11}{5} = -18$. Multiply both sides by 5 to get $a - 11 = -90$. Then add 11 to both sides: $a = -90 + 11 = -79$, so $a = -79$, which matches choice B.
**Choice A is incorrect.** $-101$ would come from $a - 11 = -90 - 12$, which is not produced by solving the equation; it does not satisfy $\frac{a-11}{5} = -18$.
**Choice C is incorrect.** $-\frac{79}{5}$ equals $-15.8$, but substituting that for $a$ gives $\frac{-15.8-11}{5} \ne -18$, so it does not satisfy the equation.
**Choice D is incorrect.** $-\frac{7}{5} = -1.4$, and substituting that value into $\frac{a-11}{5}$ does not yield $-18$, so it is not a solution.
**Faster approach:** Multiply the equation $\frac{a-11}{5} = -18$ by 5 immediately to get $a - 11 = -90$, then add 11 to get $a = -79$—a direct two-step process for any similar linear equation.'),
  ('863a0eed-c7a1-530e-b271-9646a50d1155', 0, null, '**Choice A is correct.** From the table, line $j$ has slope $m = (-4 - (-10))/(1 - 0) = 6$ and passes through $(0,-10)$, so its equation is $y = 6x - 10$. Line $k$ is $y = 4x$. Setting them equal gives $6x - 10 = 4x$, so $2x = 10$ and $x = 5$, and $y = 4(5) = 20$. The intersection is $(5,20)$.
**Choice B is incorrect.** Although it has $x = 5$, substituting into $y = 4x$ gives $y = 20$, not $44$; 44 does not lie on line $k$.
**Choice C is incorrect.** $(6,24)$ lies on $y = 4x$, but it does not satisfy $y = 6x - 10$ because $6(6) - 10 = 26$, not $24$.
**Choice D is incorrect.** $(6,26)$ lies on line $j$ but not on line $k$; for $x = 6$, $y = 4x = 24$, so $26$ is not on line $k$.
**Faster approach:** Use two table points to get slope and intercept quickly (here from $(0,-10)$ the intercept is apparent), write $y = mx + b$, then set equal to $y$ from the other line and solve one linear equation for $x$.'),
  ('61734a74-66c1-5846-b94c-2dfb4ecb050e', null, array['11/10']::text[], '**The correct answer is 1.1.** The object hits the ground when $h(t) = 0$. Given $h(t) = -16t^{2} + b$ and $b = 19.36$ (the height at $t = 0$), set $-16t^{2} + 19.36 = 0$. Solve: $16t^{2} = 19.36$, so $t^{2} = 19.36/16 = 1.21$, and $t =\sqrt{1.21} =$ $1.1$. We take the positive root since time is nonnegative.
**Faster approach:** Substitute the initial height for $b$ immediately, rearrange to $t^{2} = 19.36/16$, and take the positive square root — this requires only one division and one square-root operation.'),
  ('9e939909-7f45-52bd-bddf-f9921e28b1bc', 0, null, '**Choice A is correct.** The equation is given as
$∣4x - 3∣ = -9$
. By definition, the absolute value of any expression, such as $∣4x - 3∣$, is always non-negative. This means that the expression can only be greater than or equal to zero, never less than zero. Therefore, it is impossible for the absolute value to equal a negative number like -9. As a result, there are no solutions for this equation.
Now, let’s analyze the other options:
**Choice B (One):** This choice is incorrect because, as stated, the equation has no solutions. Thus, there cannot be just one solution.
**Choice C (Two):** This choice is incorrect for the same reason; there are not two solutions since no solutions exist.
**Choice D (Infinitely many):** This choice is also incorrect because there are no solutions to the equation, making it impossible to have infinitely many solutions.'),
  ('85292c61-7f54-52b1-88b4-b37aa47faa64', 1, null, '**Choice B is correct.** Because $h(x) = a^{x} + b$, substituting $(0,10)$ gives $a^{0} + b = 1 + b = 10$, so $b = 9$. Substituting $(2,13)$ gives $a^{2} + 9 = 13$, so $a^{2} = 4$ and, since $a > 0$, $a = 2$. Thus $ab = 2 \cdot 9 = 18$, which matches Choice B.
**Choice A is incorrect.** That choice would imply $ab = 13$, but with $b = 9$ (from the $x = 0$ point) $a$ would have to be $13/9$, which does not satisfy $a^{2} = 4$ from the $x = 2$ point.
**Choice C is incorrect.** That choice gives $ab = 20$, which would require $a = 20/9$, again not consistent with $a^{2} = 4$ determined by the second point.
**Choice D is incorrect.** That choice gives $ab = 26$, implying $a = 26/9$, which also contradicts the required $a^{2} = 4$; only $a = 2$ and $b = 9$ satisfy both given points.
**Faster approach:** Plug in $x = 0$ first to get $b$ immediately ($1 + b = 10 ⇒ b = 9$), then plug in $x = 2$ to solve $a^{2} + 9 = 13$ for $a$, and compute $ab$.'),
  ('67bbbb84-7ba2-5043-a273-b4a218e5ab27', null, array['16']::text[], '**The correct answer is 16.** The arc measure $45°$ corresponds to a central angle of $θ = 45° = π/4$ radians. Arc length $s$ is given by $s = rθ$, so $4π = r(π/4)$. Solving for $r$ gives $r = \frac{4π}{π/4} = 4π \cdot \frac{4}{π} = 16$.
**Faster approach:** Convert $45°$ to the fraction of the circle $45/360 = 1/8$, note the arc is $1/8$ of the circumference $2πr$, so $\frac{1}{8}(2π r) = 4π$ leading to $r = 16$. This fraction-of-circumference method works for any similar arc-length problem.'),
  ('4b86274f-2079-5986-8234-f20fddc98746', 3, null, '**Choice D is correct.** The ratio of successive values is $\frac{f(n)}{f(n-1)} = \frac{56(0.19)^{n}}{56(0.19)^{n-1}} = 0.19$. So $f(n)$ is $1 - 0.19 = 0.81$, or $81%$, less than $f(n - 1)$; hence $p = 81$.
**Choice A is incorrect.** $19$ would be the percent remaining (or the factor) rather than the percent decrease; the decrease is $81%$, not $19%$.
**Choice B is incorrect.** $44%$ does not match the difference $1 - 0.19 = 0.81$ and is not derived from the given base $0.19$.
**Choice C is incorrect.** $56%$ is unrelated to the base $0.19$; the percent decrease comes directly from $1 -$ $0.19 = 0.81$ (81%), so 56% is wrong.
**Faster approach:** For exponential functions $a \cdot r^{x}$, consecutive values differ by factor $r$, so percent decrease = $(1 - r) \times 100%$. Here $r = 0.19$, so $1 - 0.19 = 0.81 ⇒ 81%$.'),
  ('1888503d-4855-52b7-893f-94cd611bc3f8', 0, null, '**Choice A is correct.** For a quadratic $ax^{2} + bx + c = 0$ to have exactly one real solution, the discriminant must be zero: $b^{2} - 4ac = 0$. Here $a = 1$, $b =\sqrt{k - 3}$, and $c = 42$. So $(\sqrt{k - 3})^{2} - 4(1)(42) = 0$, which gives $k - 3 -$ $168 = 0$, hence $k = 171$. Also $k \ge 3$ so the square root is defined, and $171$ satisfies that.
**Choice B is incorrect.** Plugging $k = 168$ gives discriminant $168 - 168 = 0$ would seem to work, but note $(\sqrt{k - 3})^{2} = k - 3$, so with $k = 168$ the left becomes $165 - 168 \ne 0$; thus $k = 168$ does not satisfy $k -$ $171 = 0$.
**Choice C is incorrect.** $k = 165$ yields discriminant $165 - 171 = -6$, which is negative, so the equation would have no real solutions rather than exactly one.
**Choice D is incorrect.** $k = 45$ gives discriminant $45 - 171 = -126$, also negative, so there are no real solutions for that value.
**Faster approach:** Set discriminant $b^{2} - 4ac = 0$ immediately; here replace $b^{2}$ with $k - 3$ to get $k - 3 - 168 =$ $0$, then solve for $k$.'),
  ('6c554659-e6f4-53de-afd0-49d169e9aa78', 2, null, '**Choice C is correct.** The circle gives $y^{2} = 36 - (-5)^{2} = 36 - 25 = 11$, so the intersection has $y = \pm \sqrt{11}$. Since $y < 0$, $y = -\sqrt{11}$. Substituting $x = -5$ and $y = -\sqrt{11}$ into the line $y = mx - \frac{b}{4}$ gives $-\sqrt{11} = -5m -$ $\frac{b}{4}$. Multiply by 4 to get $-4\sqrt{11} = -20m - b$, so $b = -20m + 4\sqrt{11}$, which is choice C.
**Choice A is incorrect.** Solving for $b$ from $-5m - \frac{b}{4} = -\sqrt{11}$ does not produce $\frac{5m}{4} +\frac{\sqrt{11}}{4}$; the algebra yields different coefficients.
**Choice B is incorrect.** Like A, the signs and factors are wrong; dividing the correct equation would not produce $\frac{5m}{4} -\frac{\sqrt{11}}{4}$.
**Choice D is incorrect.** Choice D has the wrong sign on the $20m$ term and the wrong sign on the radical; it does not match $b = -20m + 4\sqrt{11}$.
**Faster approach:** Plug the given point into both equations immediately: use $x = -5$ in the circle to get $y =$ $\pm \sqrt{11}$ (choose negative), then substitute $x,y$ into the line and solve once for $b$.'),
  ('0bd4cfb4-a731-5439-b59b-6290a98edd3a', 2, null, '**Choice C is correct.** Let $x$ be grams of the $0.3%$ solution and $y$ be grams of the $0.15%$ solution. Then $x + y =$ $80$ and $0.003x + 0.0015y = 0.21$ (percentages written as decimals). Substituting $y = 80 - x$ into the second equation gives $0.003x + 0.0015(80 - x) = 0.21 ⇒ 0.003x + 0.12 - 0.0015x = 0.21 ⇒ 0.0015x = 0.09 ⇒$
$x = 60.$
**Choice A is incorrect.** $0.14$ grams is far too small; it does not satisfy the mass or salt equations (it would leave $79.86$ g of the other solution and the total salt would not be $0.21$ g).
**Choice B is incorrect.** $20$ grams would give only $0.003 \cdot 20 + 0.0015 \cdot 60 = 0.06 + 0.09 = 0.15$ g of salt, not $0.21$ g.
**Choice D is incorrect.** $79.86$ grams is the complement of choice A and similarly fails to produce the required $0.21$ g of sodium chloride when combined with the remaining small amount of the other solution.
**Faster approach:** Use alligation (weighted average). The final concentration is $0.21/80 = 0.002625$ (0.2625%). The fraction from the 0.3% solution is $(0.2625 - 0.15)/(0.3 - 0.15) = 0.1125/0.15 = 0.75$, so $0.75 \cdot 80 = 60$ g from the 0.3% solution.'),
  ('3ffff47a-f761-5183-8baf-bba423fe41cf', 2, null, '**Choice C is correct.** The 11 values in A in order are 0, 0, 3, 3, 4, 4, 5, 5, 6, 7, 13; the median (middle of 11) is the 6th value, which is $4$. Removing the 13 produces the 10 values 0, 0, 3, 3, 4, 4, 5, 5, 6, 7; the median of 10 values is the average of the 5th and 6th values, which are $4$ and $4$, so the median is $4$ — equal to the original median.
**Choice A is incorrect.** It claims the median of B is less than A, but both medians are $4$, so A is false.
**Choice B is incorrect.** It claims the median of B is greater than A, but both medians are $4$, so B is false.
**Choice D is incorrect.** There is enough information: the full frequency table lets you determine the ordered list and compute both medians exactly.
**Faster approach:** Write the ordered list from the frequency table, then use positions: for 11 values take the 6th value; after removing one value (making 10), take the average of the 5th and 6th values. Counting positions directly gives the medians quickly for any similar problem.'),
  ('43ca8394-5f9d-58e0-a580-ebf8f80eaab3', 3, null, '**Choice D is correct.** The equation is written as $\frac{x}{5} + \frac{y}{9} = \frac{47}{45}$, which can be read as $x \cdot \frac{1}{5} + y \cdot \frac{1}{9} = \frac{47}{45}$. Thus each type‑A resistor has resistance $a = \frac{1}{5}$ and each type‑B resistor has resistance $b = \frac{1}{9}$. The positive difference is $∣a - b∣ = ( \frac{1}{5} - \frac{1}{9} = ) \frac{9-5}{45} = \frac{4}{45}$.
**Choice A is incorrect.** 47 is far too large; the resistances from the equation are fractions less than 1, so their difference cannot be 47.
**Choice B is incorrect.** 4 is also too large given $a = \frac{1}{5}$ and $b = \frac{1}{9}$; their difference is a small fraction. **Choice C is incorrect.** $\frac{47}{15}$ is not equal to $( \frac{1}{5} - \frac{1}{9}$ and is much larger than the actual difference $\frac{4}{45}$. **Faster approach:** Read each term $\frac{x}{5}$ and $\frac{y}{9}$ as $x \cdot (1/5)$ and $y \cdot (1/9)$ to identify $a = 1/5$ and $b = 1/9$, then subtract to get $4/45$.'),
  ('5bf31ba7-43bd-5ffd-a616-92a369cd3731', null, array['36']::text[], '**The correct answer is 36.** Rewrite the equation in standard quadratic form: $9x^{2} - nx + 8 = 0$. For a quadratic $ax^{2} + bx + c = 0$ to have exactly one solution, its discriminant must be zero: $b^{2} - 4ac = 0$. Here $a = 9$, $b =$ $-n$, and $c = 8$, so $(-n)^{2} - 4(9)(8) = 0$, which gives $n^{2} - 288 = 0$ and therefore $n^{2} = 288$. Dividing by 8 yields $\frac{n^{2}}{8} = \frac{288}{8} = 36$.
**Faster approach:** Immediately set the discriminant $b^{2} - 4ac = 0$ for $9x^{2} - nx + 8 = 0$, compute $n^{2} -$ $4(9)(8) = 0$, and solve for $n^{2}$, then divide by 8. This avoids solving for $n$ or $x$ explicitly.'),
  ('43dc4f72-97dd-5682-84d3-cc934cbf1613', 3, null, '**Choice D is correct.** For similar figures the linear scale factor equals the square root of the ratio of areas. The area ratio is $\frac{2520}{630} = 4$, so the linear scale factor is $\sqrt{4} = 2$. Perimeters scale by the same linear factor, so rectangle B’s perimeter is $2 \times 210 = 420$, giving $n = 420$.
**Choice A is incorrect.** A value of $2100$ would correspond to multiplying the perimeter by $10$, which does not match the linear scale factor $\sqrt{2520/630} = 2$.
**Choice B is incorrect.** A value of $1680$ would correspond to multiplying the perimeter by $8$, not the correct factor of $2$ from the area ratio.
**Choice C is incorrect.** A value of $840$ would be a factor of $4$ times the original perimeter; the linear scale factor is $2$, so $210 \times 4$ is not appropriate.
**Faster approach:** Compute the area ratio, take its square root to get the linear scale factor, and multiply the known perimeter by that factor to get the unknown perimeter.'),
  ('58b8d859-66ba-537e-bff5-edaa714861b0', null, array['60000']::text[], '**The correct answer is 60000.** Let the mass of B be $b$. Since A is $444%$ of B, $A = 4.44b$. Since A is $0.740%$ of C, $A = 0.00740C$. Equate the two expressions for A: $4.44b = 0.00740C$. Solve for $C$ in terms of $b$: $C =$ $\frac{4.44}{0.00740}b = 600b$. Thus $C$ is $600$ times as large as $B$, which means $C$ is $600 \times 100% = 60000%$ of $B$, so $p =$ $60000$.
**Faster approach:** Translate the given percentages to multipliers ($444% = 4.44$, $0.740% = 0.00740$), set $4.44b = 0.00740C$, and compute $C/b = 4.44/0.00740 = 600$, then convert the factor $600$ to a percent by multiplying by $100$ to get $60000%$. This algebraic ratio method works for any similar percent-comparison problem.'),
  ('9eda255b-c31b-5a7d-a244-64bdb5dadecb', 3, null, '**Choice D is correct.** Factor $(x - 3)$ from both terms: $y^{2}(x - 3) - 25(x - 3)^{3} = (x - 3)(y^{2} - 25(x - 3)^{2})$. Recognize a difference of squares: $y^{2} - 25(x - 3)^{2} = (y - 5(x - 3))(y + 5(x - 3))$. The factor $y + 5(x - 3)$ simplifies to $y + 5x - 15$, which matches Choice D.
**Choice A is incorrect.** While $(x - 3)$ is a common factor, $y(x - 3)$ would require the remaining factor to be $y - 25(x - 3)^{2}/y$, which is not a polynomial factor; $y(x - 3)$ is not a factor of the original expression.
**Choice B is incorrect.** The expression does contain a factor $(x - 3)$ but not $(x - 5)$; there is no step that produces $(x - 5)$ as a factor, so $(x - 5)(x - 3)$ is not a factor.
**Choice C is incorrect.** The factor from the difference of squares is $y - 5(x - 3) = y - 5x + 15$, not $y - x - 3$ , so Choice C does not match any factor.
**Faster approach:** Factor out the obvious common factor $(x - 3)$, then spot the remaining expression as a difference of squares and factor as $(y - 5(x - 3))(y + 5(x - 3))$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
